class DbRepo:
    def laden(self):
        return ["Anna", "Ben", "Cem"]

class TestRepo:
    def laden(self):
        return ["Testperson"]

class Klassenliste:
    def __init__(self, repo):
        self.repo = repo  # übergeben

    def anzahl(self):
        return len(self.repo.laden())

print(Klassenliste(DbRepo()).anzahl())
# 3
print(Klassenliste(TestRepo()).anzahl())
# 1

