class A:
    def laden(self): return [1, 2, 3]
class B:
    def laden(self): return [9]
class Liste:
    def __init__(self, repo):
        self.repo = repo
    def n(self):
        return len(self.repo.laden())
print(Liste(A()).n(), "und", Liste(B()).n())
